<?php $title="Customers";require "includes/header.php";$r=$conn->query("SELECT * FROM customers ORDER BY id DESC");?><div class="section-title"><div><h2>👥 Customer 360</h2><p class="muted">Profiles and AI segments.</p></div><a class="btn primary" href="add_customer.php">+ Add Customer</a></div><div class="card"><input id="q" class="search" onkeyup="filterTable('q','t')" placeholder="Search..."><table id="t"><thead><tr><th>Customer</th><th>Phone</th><th>City</th><th>Segment</th></tr></thead><tbody><?php while($x=$r->fetch_assoc()):?><tr><td><b><?=e($x["name"])?></b><br><?=e($x["email"])?></td><td><?=e($x["phone"])?></td><td><?=e($x["city"])?></td><td><span class="badge"><?=e($x["segment"])?></span></td></tr><?php endwhile;?></tbody></table></div><?php require "includes/footer.php";?>